{
  "extracted_concepts": [
    {
      "name": "Linear Transformation",
      "aliases": ["linear map", "线性变换"],
      "definition_snippet": "A map T: V → W satisfying additivity and homogeneity.",
      "category": "concept"
    },
    {
      "name": "Additivity",
      "aliases": ["addition preservation", "加法保持"],
      "definition_snippet": "T(u + v) = T(u) + T(v).",
      "category": "property"
    },
    {
      "name": "Homogeneity",
      "aliases": ["scalar multiplication preservation", "齐次性"],
      "definition_snippet": "T(cu) = cT(u).",
      "category": "property"
    },
    {
      "name": "Rotation",
      "aliases": ["旋转"],
      "definition_snippet": "A linear transformation that rotates vectors in R² or R³.",
      "category": "concept"
    },
    {
      "name": "Reflection",
      "aliases": ["反射"],
      "definition_snippet": "A linear transformation that reflects vectors in R² or R³.",
      "category": "concept"
    },
    {
      "name": "Projection",
      "aliases": ["投影"],
      "definition_snippet": "A linear transformation that projects vectors onto a subspace.",
      "category": "concept"
    },
    {
      "name": "Differentiation",
      "aliases": ["differentiation operator", "微分"],
      "definition_snippet": "The linear operator D(p) = p'.",
      "category": "operation"
    },
    {
      "name": "Integration",
      "aliases": ["integration operator", "积分"],
      "definition_snippet": "The operator p ↦ ∫₀ˣ p(t) dt.",
      "category": "operation"
    },
    {
      "name": "Kernel",
      "aliases": ["null space", "核"],
      "definition_snippet": "Ker(T) = {v ∈ V : T(v) = 0}.",
      "category": "concept"
    },
    {
      "name": "Image",
      "aliases": ["range", "像"],
      "definition_snippet": "Im(T) = {T(v) : v ∈ V}.",
      "category": "concept"
    },
    {
      "name": "Rank-Nullity Theorem",
      "aliases": ["dimension theorem", "秩-零化度定理"],
      "definition_snippet": "dim(Ker T) + dim(Im T) = dim(V).",
      "category": "theorem"
    },
    {
      "name": "Matrix Representation",
      "aliases": ["matrix of a linear transformation", "矩阵表示"],
      "definition_snippet": "A matrix A such that [T(v)]_B = A[v]_B.",
      "category": "concept"
    },
    {
      "name": "Basis",
      "aliases": ["基"],
      "definition_snippet": "A linearly independent spanning set for a vector space.",
      "category": "concept"
    },
    {
      "name": "Coordinate Vector",
      "aliases": ["coordinates", "坐标向量"],
      "definition_snippet": "The coordinate array [v]_B relative to a basis B.",
      "category": "concept"
    },
    {
      "name": "Composition of Transformations",
      "aliases": ["transformation composition", "变换复合"],
      "definition_snippet": "Applying one linear transformation after another.",
      "category": "operation"
    },
    {
      "name": "Matrix Multiplication",
      "aliases": ["矩阵乘法"],
      "definition_snippet": "Multiplication of matrices representing composition.",
      "category": "operation"
    },
    {
      "name": "Change of Basis",
      "aliases": ["basis change", "基变换"],
      "definition_snippet": "Replacing one basis by another to describe the same space.",
      "category": "operation"
    },
    {
      "name": "Transition Matrix",
      "aliases": ["change-of-basis matrix", "过渡矩阵"],
      "definition_snippet": "P satisfies [x]_B = P[x]_B'.",
      "category": "concept"
    },
    {
      "name": "Similar Matrix Representation",
      "aliases": ["similar matrix", "相似矩阵表示"],
      "definition_snippet": "The matrix in a new basis is A' = P^(-1) A P.",
      "category": "concept"
    },
    {
      "name": "Inner Product",
      "aliases": ["内积"],
      "definition_snippet": "A map ⟨u, v⟩ satisfying symmetry, linearity, and positive definiteness.",
      "category": "concept"
    },
    {
      "name": "Dot Product",
      "aliases": ["Euclidean inner product", "点积"],
      "definition_snippet": "⟨u, v⟩ = u₁v₁ + u₂v₂ + ... + uₙvₙ in Rⁿ.",
      "category": "concept"
    },
    {
      "name": "Symmetry",
      "aliases": ["对称性"],
      "definition_snippet": "⟨u, v⟩ = ⟨v, u⟩.",
      "category": "property"
    },
    {
      "name": "Linearity of Inner Product",
      "aliases": ["inner-product linearity", "内积线性"],
      "definition_snippet": "The inner product is linear in its vector argument.",
      "category": "property"
    },
    {
      "name": "Positive Definiteness",
      "aliases": ["正定性"],
      "definition_snippet": "⟨v, v⟩ ≥ 0, with equality only when v = 0.",
      "category": "property"
    },
    {
      "name": "Orthogonality",
      "aliases": ["orthogonal vectors", "正交性"],
      "definition_snippet": "Vectors u and v are orthogonal if ⟨u, v⟩ = 0.",
      "category": "concept"
    },
    {
      "name": "Gram-Schmidt Process",
      "aliases": ["Gram-Schmidt orthogonalization", "格拉姆-施密特过程"],
      "definition_snippet": "Converts a basis into an orthonormal basis.",
      "category": "operation"
    },
    {
      "name": "Orthonormal Basis",
      "aliases": ["标准正交基"],
      "definition_snippet": "A basis whose vectors are mutually orthogonal unit vectors.",
      "category": "concept"
    },
    {
      "name": "Least Squares Solution",
      "aliases": ["least squares approximation", "最小二乘解"],
      "definition_snippet": "x̂ = (A^T A)^(-1) A^T b gives the best approximate solution.",
      "category": "operation"
    },
    {
      "name": "Orthogonal Projection",
      "aliases": ["orthogonal projection onto subspace", "正交投影"],
      "definition_snippet": "Proj_W v = Σᵢ ⟨v, qᵢ⟩qᵢ for an orthonormal basis {qᵢ}.",
      "category": "operation"
    }
  ],
